package main

import (
	"context"
	"log"

	"github.com/ThreadifyDev/go-sdk"
)

func main() {
	ctx := context.Background()

	// Connect with your API key
	conn, err := threadify.Connect(ctx, "YOUR_API_KEY", threadify.WithServiceName("my-service"))
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close()

	// Start tracking a workflow with a descriptive label
	thread, err := conn.Start(ctx, "Order-Processing-ORD-12345", "")
	if err != nil {
		log.Fatal(err)
	}

	// Record each step with full context
	_, err = thread.Step("order_placed").
		AddContext(map[string]any{
			"order_id": "ORD-12345",
			"amount":   99.99,
		}).
		Success(ctx)
	if err != nil {
		log.Fatal(err)
	}

	_, err = thread.Step("payment_processed").
		AddContext(map[string]any{
			"payment_id": "PAY-67890",
		}).
		Success(ctx)
	if err != nil {
		log.Fatal(err)
	}
}

