import { Threadify } from '@threadify/sdk';

const connection = await Threadify.connect('YOUR_API_KEY', 'my-service');

// Subscribe to violations
connection.subscribe('rule.violated', 'payment_processed', (notification) => {
  console.log('Payment violation:', notification.severity);
  // Implement circuit breaker, retry logic, etc.
  notification.ack(); // IMPORTANT: Must ACK
});

// Subscribe to completions
connection.subscribe('step.success', 'order_delivered', (notification) => {
  console.log('Order delivered:', notification.stepName);
  // Send confirmation email, update analytics, etc.
  notification.ack();
});

// Subscribe to failures
connection.subscribe('step.failed', 'payment_processed', (notification) => {
  console.log('Payment failed:', notification.stepName);
  notification.ack();
});

