package main

import (
	"context"
	"fmt"
	"log"

	"github.com/ThreadifyDev/go-sdk"
)

func main() {
	ctx := context.Background()
	conn, err := threadify.Connect(ctx, "YOUR_API_KEY")
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close()

	// Subscribe to violations
	err = conn.Subscribe(ctx, "rule.violated", "payment_processed", func(n *threadify.Notification) {
		fmt.Println("Payment violation:", n.Severity)
		// Implement circuit breaker, retry logic, etc.
		n.Ack() // IMPORTANT: Must ACK
	})
	if err != nil {
		log.Fatal(err)
	}

	// Subscribe to completions
	err = conn.Subscribe(ctx, "step.success", "order_delivered", func(n *threadify.Notification) {
		fmt.Println("Order delivered:", n.StepName)
		// Send confirmation email, update analytics, etc.
		n.Ack()
	})
	if err != nil {
		log.Fatal(err)
	}

	// Keep running
	select {}
}

