import { trace } from '@opentelemetry/api';
import { BasicTracerProvider, SimpleSpanProcessor } from '@opentelemetry/sdk-trace-base';
import { Threadify } from '@threadify/sdk';

// 1. Establish your Threadify Connection
const connection = await Threadify.connect('YOUR_API_KEY', 'checkout-service');

// 2. Create the Threadify Exporter (extracting specific OTel attributes into Threadify Refs)
const exporter = connection.createSpanExporter({ refs: ['order.id'] });

// 3. Register with OpenTelemetry
const provider = new BasicTracerProvider();
provider.addSpanProcessor(new SimpleSpanProcessor(exporter));
trace.setGlobalTracerProvider(provider);

// Now all your standard OTel spans automatically become Threadify execution graphs!
const tracer = trace.getTracer('my-service-tracer');
const span = tracer.startSpan('process_payment');
// ... business logic ...
span.end();

