package main

import (
	"context"
	"log"

	threadify "github.com/ThreadifyDev/go-sdk"
	threadifyotel "github.com/ThreadifyDev/go-sdk/otel"
	"go.opentelemetry.io/otel"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
)

func main() {
	ctx := context.Background()

	// 1. Connect to Threadify
	conn, err := threadify.Connect(ctx, "YOUR_API_KEY")
	if err != nil {
		log.Fatal(err)
	}

	// 2. Create the Exporter
	exporter := threadifyotel.NewSpanExporter(conn, threadifyotel.SpanExporterOptions{
		Refs: []string{"order.id"},
	})

	// 3. Register with OpenTelemetry
	provider := sdktrace.NewTracerProvider(sdktrace.WithBatcher(exporter))
	otel.SetTracerProvider(provider)
	defer provider.Shutdown(ctx)

	// Now all your standard OTel spans automatically become Threadify execution graphs!
	tracer := otel.Tracer("my-service-tracer")
	_, span := tracer.Start(ctx, "process_payment")
	// ... business logic ...
	span.End()
}
